class Solution {
 public:
  int numberOfGoodSubarraySplits(vector<int>& nums) {
    if (ranges::count(nums, 1) == 0)
      return 0;

    constexpr int kMod = 1'000'000'007;
    int prev = -1;  // the previous index of 1
    int ans = 1;

    for (int i = 0; i < nums.size(); ++i)
      if (nums[i] == 1) {
        if (prev != -1)
          ans = static_cast<long>(ans) * (i - prev) % kMod;
        prev = i;
      }

    return ans;
  }
};

