class Solution {
 public:
  int minimumRightShifts(vector<int>& nums) {
    int count = 0;
    int pivot = -1;

    for (int i = 0; i + 1 < nums.size(); i++)
      if (nums[i] > nums[i + 1]) {
        ++count;
        pivot = i;
      }

