      int j = stack.pop();
      // The last abs(j - stack.peek()) heights are `heights[j]`.
      sum -= (long) Math.abs(j - stack.peek()) * heights[j];
    }
    // Put abs(i - stack.peek()) * heights[i] in `heights`.
    sum += (long) Math.abs(i - stack.peek()) * heights[i];
    stack.push(i);
    return sum;
  }
