class Solution {
 public:
  long long maxScore(vector<int>& prices) {
    //    prices[indices[j]] - prices[indices[j - 1]]
    // == indices[j] - indices[j - 1]
    //    prices[indices[j]] - indices[j]
    // == prices[indices[j - 1]] - indices[j - 1]
    //
