    final int MAX_BIT = 30;
    int ans = 0;

    for (int i = 0; i <= MAX_BIT; ++i) {
      final int finalI = i;
      final int count = (int) Arrays.stream(nums)
                            .filter(num -> (num >> finalI & 1) == 1) //
